BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats14-q01', 'ベイズ統計の応用',
   '新作のサイコロが『6の目が出やすいよう細工されているのでは』と疑い、これから何回か振って確かめたい。何も手がかりが無いので『1〜6のどの目も同じ確率(1/6)だろう』とみなしてスタートする事前分布と、同じ工場が作った別のサイコロを過去に1000回振った記録から『6の出る確率はだいたい25%』とすでに分かっていて、そこから出発する事前分布は、それぞれ何と呼ばれる？',
   NULL::text,
   '["前者は無情報事前分布、後者は情報事前分布。手がかりが無ければ均等に、データがあれば反映してスタートする。", "前者は情報事前分布、後者は無情報事前分布。均等に置くこと自体が『情報』を使っている証拠だと考える。", "どちらも無情報事前分布。過去のデータがあっても、ベイズ更新をする前の段階ではまだ反映されていない。", "どちらも情報事前分布。目が1〜6のどれかしか出ないと分かっていること自体が、すでに立派な情報だと考えるから。"]',
   0, '[0]', 'single',
   '{"asked": "証拠(データ)を見る前、事前分布をどこから出発させるかの2つの流儀。", "point": "手がかりが無ければ均等に置く＝無情報事前分布。過去のデータや知識があれば反映して置く＝情報事前分布。", "kid": "事前分布は『証拠を見る前の、最初の見込みの形』。何も知らなければ全部同じくらいと置き、すでに知っていることがあれば、それを織り込んだ形からスタートする。", "eg": "初めて入る店でメニューを選ぶとき、何の情報も無ければ『どれも同じくらい美味しそう』と思って選ぶ(無情報)。友達から『ここはカレーが美味しい』と聞いていれば、その情報を踏まえてカレーに寄せて選ぶ(情報事前分布)。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">事前分布をどこから出発させるか</text>\n<text x=\"87\" y=\"34\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">無情報事前分布</text>\n<rect x=\"30\" y=\"98\" width=\"14\" height=\"24\" fill=\"#3b82f6\"/><rect x=\"49\" y=\"98\" width=\"14\" height=\"24\" fill=\"#3b82f6\"/><rect x=\"68\" y=\"98\" width=\"14\" height=\"24\" fill=\"#3b82f6\"/><rect x=\"87\" y=\"98\" width=\"14\" height=\"24\" fill=\"#3b82f6\"/><rect x=\"106\" y=\"98\" width=\"14\" height=\"24\" fill=\"#3b82f6\"/><rect x=\"125\" y=\"98\" width=\"14\" height=\"24\" fill=\"#3b82f6\"/>\n<text x=\"87\" y=\"132\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">6つの目、みんな同じ高さ</text>\n<line x1=\"170\" y1=\"20\" x2=\"170\" y2=\"128\" stroke=\"#2a2f3f\"/>\n<text x=\"253\" y=\"34\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">情報事前分布</text>\n<rect x=\"196\" y=\"112\" width=\"14\" height=\"10\" fill=\"#3b82f6\"/><rect x=\"215\" y=\"108\" width=\"14\" height=\"14\" fill=\"#3b82f6\"/><rect x=\"234\" y=\"104\" width=\"14\" height=\"18\" fill=\"#3b82f6\"/><rect x=\"253\" y=\"100\" width=\"14\" height=\"22\" fill=\"#3b82f6\"/><rect x=\"272\" y=\"94\" width=\"14\" height=\"28\" fill=\"#3b82f6\"/><rect x=\"291\" y=\"72\" width=\"14\" height=\"50\" fill=\"#60a5fa\"/>\n<text x=\"298\" y=\"66\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">6の目だけ高い</text>\n<text x=\"253\" y=\"132\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">過去のデータを反映</text>\n</svg>", "terms": [["無情報事前分布", "何も手がかりが無い状態から、均等に近い形でスタートする事前分布"], ["情報事前分布", "過去のデータや知識を反映した形からスタートする事前分布"]], "think": "なぜ2つの流儀があるのかがカギ。事前分布はベイズ更新の出発点であり、証拠(今回振った結果)と掛け合わされて事後分布になる。もし本当に何も手がかりが無いなら、特定の目に肩入れせず均等に置くのが自然(無情報事前分布)。逆に、同じ工場の別のサイコロのデータのように使える情報があるなら、それを最初から織り込んだほうが、少ない試行回数でも早く真実に近づける。だからデータの有無に応じて出発点を使い分ける。", "vs": "『情報が無いから無情報事前分布を使う』のと『情報を軽視して無情報事前分布を使う』は違う。使える情報があるのに使わないのは、もったいない選択になる。", "why_asked": "ベイズ更新は事前分布を出発点にする以上、出発点の選び方そのものが結果に影響する。これまでのベイズ更新(既存セット)は事前確率をすでに与えられたものとして使ってきたが、実際にはその数字自体をどう決めるかという選択が最初にある。", "usecase": "新商品の売れ行き予測(市場データが無ければ均等に、似た商品のデータがあれば反映)、新薬の効果推定(過去の類似薬のデータを情報事前分布として使う)など。", "opt": ["正解。手がかりが無ければ均等に置く無情報事前分布、過去のデータがあれば反映して置く情報事前分布。呼び方と中身が正しく対応している。", "呼び方が入れ替わっている。均等に置くのは『情報が無い』ことの表れであり無情報事前分布、データを反映するのが情報事前分布。", "過去のデータは、まだベイズ更新(今回サイコロを振った結果を反映する作業)をしていないだけで、事前分布を決める材料としてすでに使われている。無情報事前分布ではない。", "目が1〜6と分かっていることは『これから何が起こりうるか』という前提であって、『6が出やすいかどうか』についての知識(情報)ではない。前者は無情報事前分布のままでよい。"]}'),

  ('stats14-q02', 'ベイズ統計の応用',
   'コイン投げで『表が出る確率』を、ベータ分布という形の事前分布からスタートしてベイズ更新すると、更新後の事後分布もやはりベータ分布の形のまま、山の位置と尖り方だけが変わる、という都合の良い組み合わせが知られている。この関係を何と呼ぶ？',
   NULL::text,
   '["共役事前分布。事前分布と事後分布が同じ種類の分布のままになる、相性の良い組み合わせを指す。", "ベイズ更新。証拠が増えるたびに事後確率を計算し直す、更新の手続きそのものを指す言葉。", "情報事前分布。過去のデータや知識を、事前分布の形にあらかじめ反映しておくことを指す言葉。", "事後確率。証拠を見たあとに計算し直された確率の値そのものを指す言葉で、分布の形の話ではない。"]',
   0, '[0]', 'single',
   '{"asked": "事前分布と事後分布が同じ種類の分布になる、という相性の良い組み合わせの名前。", "point": "『事前分布と事後分布が同じ種類の分布になる組み合わせ』が共役事前分布。むずかしい数式を解かずに済む、いわば近道。", "kid": "ふつう、事前分布を証拠で更新すると事後分布は元とは違う複雑な形になりがち。でも事前分布の選び方によっては、更新しても『同じ種類の分布のまま、パラメータだけ変わる』という都合の良い組み合わせがある。これが共役事前分布。", "eg": "折り紙で『鶴の折り方』と『鶴の色を変える工程』が相性良く組み合わさっていて、色を変えても鶴の形は崩れないようなもの。事前分布(鶴の形)に証拠(色)を足しても、同じ鶴の形(同じ種類の分布)のままでいてくれる。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">同じ種類の分布のまま更新できる組み合わせ</text>\n<text x=\"80\" y=\"40\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">事前分布(ベータ分布)</text>\n<path d=\"M30,90 Q80,50 130,90\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<text x=\"170\" y=\"68\" fill=\"#8892a4\" font-size=\"12\" text-anchor=\"middle\">→</text>\n<text x=\"170\" y=\"82\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">証拠で更新</text>\n<text x=\"260\" y=\"40\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">事後分布(ベータ分布)</text>\n<path d=\"M210,90 Q252,42 300,90\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/>\n<text x=\"170\" y=\"112\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">山の位置と尖り方だけが変わる</text>\n<text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">同じ種類の分布のまま＝共役事前分布</text>\n</svg>", "terms": [["共役事前分布", "ベイズ更新しても事前分布と同じ種類の分布のままになる、相性の良い事前分布"], ["ベータ分布", "0〜1の間の確率を表すのに使われる、コインの表が出る確率のような値の事前分布としてよく使われる分布の形"]], "think": "なぜ『同じ種類のまま』だと都合が良いのかがカギ。事前分布と証拠を掛け合わせて事後分布を求める計算は、分布の形によっては複雑な数式が必要になる。ところが共役事前分布を選んでおくと、更新後もパラメータ(山の位置や尖り方を決める数字)を機械的に足し引きするだけで事後分布が求まり、複雑な数式を解かずに済む。だから計算を簡単にしたいときに、あえてこの組み合わせを選ぶ。", "vs": "情報事前分布は『何を知っているかで事前分布の形を決める』話。共役事前分布は『どの形を選ぶと計算が楽になるか』という、別の軸の話。情報の有無ではなく、計算のしやすさに関する区別。", "why_asked": "むずかしい数式を避けたいこのドリルでは踏み込まないが、実務でベイズ統計を計算に使うとき、共役事前分布を選べるかどうかで手計算できるか・後述のMCMCのような近似計算に頼るかが変わってくる。存在だけでも知っておくと、この先の話がつながりやすくなる。", "usecase": "コイン投げや不良品率のように『0〜1の確率』を推定するときにベータ分布を事前分布に選ぶ、平均のようにマイナスも取りうる値を推定するときに正規分布を事前分布に選ぶ、など、統計ソフトの内部でもよく使われる組み合わせ。", "opt": ["正解。事前分布と事後分布が同じ種類の分布のままになる、計算の相性が良い組み合わせを共役事前分布と呼ぶ。", "ベイズ更新は、証拠が増えるたびに確率を計算し直す手続き全般の名前。共役かどうかに関わらず、どんな事前分布でも行われる作業。", "情報事前分布は『何を知っているか』で事前分布の中身を決める話。今回の『分布の形が保たれるか』という計算上の相性の話とは別の軸。", "事後確率は証拠を見たあとの確率の値そのもの。今回問われているのは値ではなく、分布の『種類』が保たれるかどうかという話。"]}'),

  ('stats14-q03', 'ベイズ統計の応用',
   '工場ラインの不良率を推定する。方法①は、検品データが届くたびに『前回の事後分布→今回の事前分布』として1件ずつ逐次的に更新していくやり方。方法②は、1週間分のデータをすべて集めてから、最初の事前分布に対して一度にまとめて計算するやり方。この2つの方法、最終的にたどり着く事後分布はどうなる？',
   NULL::text,
   '["同じデータを使う限り、①も②も最終的にたどり着く事後分布は同じになる。", "①のほうが証拠を段階的に反映する分、②よりも極端に自信過剰な事後分布になる。", "②のほうがデータをまとめて扱う分、①よりも極端に自信過剰な事後分布になる。", "①と②はそもそも異なる計算方法なので、同じデータを使っても事後分布は必ず違う形になる。"]',
   0, '[0]', 'single',
   '{"asked": "証拠を1件ずつ逐次的に反映しても、まとめて一度に反映しても、最終的な答えは同じになるという性質。", "point": "同じデータを使うなら、逐次更新でもバッチ更新でも、たどり着く事後分布は同じ。順番や刻み方は答えを変えない。", "kid": "1件ずつコツコツ更新していっても、後でまとめて一気に計算しても、最終的に『不良率はだいたいこれくらい』とたどり着く答えは同じになる。計算の刻み方は結果を変えない。", "eg": "貯金箱に毎日100円ずつ1週間入れても、1週間分の700円を最後にまとめて入れても、貯金箱の中身は同じ700円になる。ベイズ更新も同じで、証拠を少しずつ足しても、まとめて足しても、たどり着く先は変わらない。", "viz": "<svg viewBox=\"0 0 340 144\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">1件ずつ更新しても、まとめて計算しても</text>\n<text x=\"60\" y=\"36\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">①逐次更新</text>\n<rect x=\"20\" y=\"46\" width=\"26\" height=\"16\" fill=\"#2a2f3f\"/><text x=\"33\" y=\"58\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">事前</text>\n<text x=\"55\" y=\"58\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">→</text>\n<rect x=\"62\" y=\"46\" width=\"26\" height=\"16\" fill=\"#3b82f6\"/><text x=\"75\" y=\"58\" fill=\"#e8eaf0\" font-size=\"7.5\" text-anchor=\"middle\">1日目</text>\n<text x=\"97\" y=\"58\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">→</text>\n<rect x=\"104\" y=\"46\" width=\"26\" height=\"16\" fill=\"#3b82f6\"/><text x=\"117\" y=\"58\" fill=\"#e8eaf0\" font-size=\"7.5\" text-anchor=\"middle\">2日目</text>\n<text x=\"139\" y=\"58\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">→…</text>\n<text x=\"60\" y=\"90\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">②バッチ更新</text>\n<rect x=\"20\" y=\"100\" width=\"26\" height=\"16\" fill=\"#2a2f3f\"/><text x=\"33\" y=\"112\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">事前</text>\n<text x=\"55\" y=\"112\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">→</text>\n<rect x=\"62\" y=\"100\" width=\"68\" height=\"16\" fill=\"#3b82f6\"/><text x=\"96\" y=\"112\" fill=\"#e8eaf0\" font-size=\"7.5\" text-anchor=\"middle\">1週間分まとめて</text>\n<line x1=\"200\" y1=\"30\" x2=\"200\" y2=\"118\" stroke=\"#2a2f3f\" stroke-dasharray=\"3 2\"/>\n<rect x=\"215\" y=\"60\" width=\"90\" height=\"30\" fill=\"#60a5fa\" opacity=\"0.85\"/>\n<text x=\"260\" y=\"79\" fill=\"#141720\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"700\">同じ事後分布</text>\n</svg>", "terms": [["逐次ベイズ更新", "証拠が届くたびに、前回の事後分布を次の事前分布として使い、1件ずつ更新していくやり方"], ["バッチ更新", "データをまとめてから、最初の事前分布に対して一度に計算するやり方"]], "think": "なぜ順番を変えても同じ答えになるのかがカギ。ベイズ更新は『事前分布×新しい証拠の尤度』を掛け合わせて事後分布を作る計算。掛け算は何個の数をどんな順番で掛けても答えが変わらない(2×3×4も、2×(3×4)も、(2×3)×4も同じ24になる)のと同じで、証拠をひとつずつ掛けていっても、まとめて掛けても、最終的な積は変わらない。だから1件ずつ届くデータでも、後からまとめて届くデータでも、同じように正しく扱える。", "vs": "『①のほうが証拠を大事に扱うから自信過剰になる』というのは誤解。掛け算の性質上、刻み方は答えの中身(自信の強さ)には影響しない。影響するのはあくまで証拠(データ)の量と中身。", "why_asked": "実際のデータは1件ずつ届くこと(毎日の検品、毎回のクリック)もあれば、まとめて届くこと(月末にまとめて集計)もある。どちらの届き方でも同じ手順(前回の事後分布を次の事前分布にする)で正しく扱えると分かっていないと、データの届き方が変わるたびに計算方法に迷うことになる。", "usecase": "センサーが1秒ごとに送ってくるデータをリアルタイムで少しずつ反映するシステムでも、月末にまとめて集計するレポートでも、同じベイズ更新の考え方をそのまま使える。", "opt": ["正解。掛け算の順番を変えても積が変わらないのと同じ理由で、証拠を1件ずつ反映しても、まとめて反映しても、最終的な事後分布は同じになる。", "段階的に反映するかどうかは、事後分布の『自信の強さ(尖り方)』を左右しない。左右するのはデータの量と中身であり、刻み方ではない。", "まとめて反映するかどうかも同様に、事後分布の自信の強さを左右する要因ではない。同じデータなら結果は同じになる。", "掛け算は順序によらず答えが変わらない性質を持つため、証拠の刻み方を変えても同じデータであれば事後分布は一致する。"]}'),

  ('stats14-q04', 'ベイズ統計の応用',
   'ある観光地の来月の来客数について、ベイズ更新の結果、事後分布は『8000人である確率が一番高く、7000人や9000人はそれよりやや低い確率、6000人や10000人はさらに低い確率』という山形になった。この事後分布から『来月の来客数はこれだ』とひとつの数字を選ぶとき、確率が一番高い8000人を答えとして選ぶ考え方を何と呼ぶ？',
   NULL::text,
   '["MAP推定（最大事後確率推定）。事後分布の中で確率が一番高い1点を答えとして選ぶ考え方。", "信用区間。事後分布の中で、真の値がある可能性が高い範囲を、1点ではなく幅で示す考え方。", "尤度。ある原因(仮説)を仮定したときに、その結果がどれくらい出やすいかを表す確率のこと。", "ベイズ更新。証拠が増えるたびに、前回の事後分布を次の事前分布として計算し直す手続き。"]',
   0, '[0]', 'single',
   '{"asked": "事後分布の中で一番確率が高い1点を『答え』として選ぶ考え方の名前。", "point": "MAP推定は、事後分布のグラフの一番高い山の頂上にある値を、代表の1点として選ぶやり方。", "kid": "事後分布は『どの値がどれくらいありそうか』という山の形をしている。MAP推定は、その山の中で一番高いところ(一番ありそうな値)を、代表としてひとつだけ選ぶ考え方。", "eg": "クラス全員の身長を測ってヒストグラムを作ったとき、一番人数が多い身長の階級を『このクラスの代表的な身長』として選ぶようなもの。山の一番高いところを代表に選ぶ発想はMAP推定と同じ。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">事後分布の中で一番高いところを選ぶ</text>\n<path d=\"M30,100 C90,100 100,30 170,30 C240,30 250,100 310,100\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<line x1=\"170\" y1=\"30\" x2=\"170\" y2=\"104\" stroke=\"#c9a04a\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/>\n<circle cx=\"170\" cy=\"30\" r=\"4\" fill=\"#c9a04a\"/>\n<text x=\"90\" y=\"115\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">7000人</text>\n<text x=\"250\" y=\"115\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">9000人</text>\n<text x=\"170\" y=\"133\" fill=\"#c9a04a\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">MAP推定＝8000人（山の頂上）</text>\n</svg>", "terms": [["MAP推定", "事後分布の中で、確率が一番高い1点を答えとして選ぶ考え方。Maximum A Posteriori(最大事後確率)の略"], ["事後分布", "証拠を反映したあとの、値ごとのありそうさを表す分布の形"]], "think": "なぜ『山の頂上』を選ぶのかがカギ。事後分布はすでに証拠(これまでの来客数の記録など)を織り込んだ、いま持っている情報のすべて。この分布は『どの値が一番もっともらしいか』という高さの違いを表しているので、一番高いところを選ぶことは、いま手元にある証拠のもとで一番ありそうな値をひとつ選ぶことに等しい。だから代表の1点としてふさわしい。", "vs": "平均値も事後分布から1つの数字を選ぶ方法だが、山の形が左右非対称だと、平均値と山の頂上(MAP推定)は違う値になることがある。『代表の1点』にも複数の選び方があることに注意。", "why_asked": "事後分布はそのままだと『山の形』という情報の塊で、意思決定にはひとつの数字がほしい場面が多い(来月の仕入れ数を決める、など)。事後分布から具体的な数字を取り出す代表的なやり方のひとつがMAP推定。", "usecase": "来月の売上予測をひとつの数字で報告したいとき、機械学習で『一番それらしいカテゴリ』をひとつ選んで分類結果として出すときなど、分布そのものではなく1つの答えがほしい場面で使う。", "opt": ["正解。事後分布の中で確率が一番高い1点(8000人)を答えとして選ぶのがMAP推定。", "信用区間は1点ではなく『この範囲にありそう』という幅で表す考え方。今回問われているのは1点を選ぶ方法。", "尤度は原因を仮定したときの結果の出やすさを表す確率で、事後分布から代表点を選ぶ方法の名前ではない。", "ベイズ更新は事前分布から事後分布を計算し直す手続きそのもの。今回問われているのは、できあがった事後分布から1点を選ぶ方法の名前。"]}'),

  ('stats14-q05', 'ベイズ統計の応用',
   '推測統計で学んだ『信頼区間95%』は、実は『真の値がこの範囲にある確率が95%』とは言えない、というやや意外な決まりがある。一方ベイズ統計の『信用区間95%』は、『真の値がこの範囲にある確率が95%』と直接言い切ってよい。この2つの解釈の違いが生まれる理由は？',
   NULL::text,
   '["信頼区間は『手順を繰り返した割合』を表すのに対し、信用区間は事後分布から『真の値がある確率』を直接表すから。", "信頼区間は事後分布から計算されるのに対し、信用区間は標本のデータだけを使って直接計算されているから、という違い。", "信頼区間のほうが信用区間より広い範囲を指すので、確率の言い方も強めに言い切れてしまうから。", "信頼区間と信用区間はどちらも同じ計算方法で、呼び方が違うだけの見た目上の違いにすぎないから。"]',
   0, '[0]', 'single',
   '{"asked": "信頼区間と信用区間、どちらも『それらしい範囲』を示すのに、言い切り方が違う理由。", "point": "信頼区間は『手順を繰り返したときに区間が真の値を含む割合』、信用区間は『真の値がその範囲にある確率』を直接言える範囲。", "kid": "信頼区間95%は、『もし同じ調査を100回繰り返したら、そのうち95回くらいは真の値を区間の中に捕まえられるはず』という、手順についての約束。信用区間95%は、事後分布そのものから計算されるので、『この範囲に真の値がある確率は95%』とそのまま言い切ってよい。", "eg": "信頼区間は『輪投げを100回やったら95回は輪が棒に入るはずの、投げ方のクセ』を言っているようなもの。今投げた1本の輪が本当に棒に入っているかどうかは、それだけでは分からない。信用区間は『今の情報から見て、輪が入っている確率は95%』と、今投げたその1本について直接言っている。", "viz": "<svg viewBox=\"0 0 340 144\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"90\" y=\"16\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">信頼区間（繰り返しの割合）</text>\n<line x1=\"150\" y1=\"24\" x2=\"150\" y2=\"128\" stroke=\"#2a2f3f\"/>\n<line x1=\"20\" y1=\"34\" x2=\"65\" y2=\"34\" stroke=\"#3b82f6\" stroke-width=\"2\"/><line x1=\"18\" y1=\"44\" x2=\"60\" y2=\"44\" stroke=\"#3b82f6\" stroke-width=\"2\"/><line x1=\"24\" y1=\"54\" x2=\"70\" y2=\"54\" stroke=\"#3b82f6\" stroke-width=\"2\"/><line x1=\"20\" y1=\"64\" x2=\"62\" y2=\"64\" stroke=\"#c47070\" stroke-width=\"2\"/><line x1=\"22\" y1=\"74\" x2=\"68\" y2=\"74\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n<line x1=\"45\" y1=\"26\" x2=\"45\" y2=\"82\" stroke=\"#8892a4\" stroke-dasharray=\"2 2\"/>\n<text x=\"90\" y=\"98\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">100回繰り返すと</text>\n<text x=\"90\" y=\"110\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">95回くらい真の値を含む</text>\n<text x=\"250\" y=\"16\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">信用区間（直接の確率）</text>\n<path d=\"M195,80 C210,30 250,30 250,30 C250,30 290,30 305,80\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/>\n<path d=\"M212,78 C222,45 250,42 250,42 C250,42 278,45 288,78 Z\" fill=\"#60a5fa\" opacity=\"0.35\"/>\n<text x=\"250\" y=\"98\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">この範囲に真の値がある確率95%</text>\n</svg>", "terms": [["信頼区間", "推測統計での区間の作り方。『同じ手順を繰り返すと、区間が真の値を含む割合が95%になる』という意味で、1回の区間そのものに確率は付けられない"], ["信用区間", "ベイズ統計での区間の作り方。事後分布から直接『真の値がこの範囲にある確率』を計算するので、そのまま確率として言い切れる"]], "think": "なぜ言い切り方が違うのかがカギ。頻度主義に立つ信頼区間は、真の値を『すでに決まっているがまだ分からない、ひとつの固定された数』とみなす。固定された数に対しては『含む確率』という言い方ができず、代わりに『手順を繰り返したときにどれくらいの割合で捕まえられるか』を約束する。一方ベイズ主義に立つ信用区間は、真の値についての確信そのものを事後分布という確率の形で持っているので、その分布から直接『この範囲にある確率は95%』と言い切れる。", "vs": "『信頼区間も信用区間も、同じ95%という数字だから同じ意味だろう』が一番の誤解ポイント。数字が同じでも、頻度主義とベイズ主義という立場の違いにより、言ってよいことの範囲が違う。", "why_asked": "推測統計(既存セット)で信頼区間を学んだ人ほど、『95%の確率で真の値が入っている』とつい言ってしまいがちだが、これは頻度主義の信頼区間では誤った言い方。ベイズ統計の信用区間ならその言い方が正しくなる、という対比を理解しているかを確かめる。", "usecase": "選挙の当選確率をベイズ統計で『当選する確率は80%』と直接報道するのは信用区間的な発想。一方、工場の品質管理で『この工程なら95%の確率で規格内に収まる手順になっている』と手順そのものを保証したいときは信頼区間的な発想が使われる。", "opt": ["正解。信頼区間は繰り返した手順が真の値を捕まえる割合、信用区間は事後分布から直接求めた『真の値がある確率』。この違いが言い切り方の違いを生む。", "信頼区間も標本のデータから計算される。事後分布を使うかどうかではなく、確率をどう解釈するか(頻度かベイズか)の違いが本質。", "区間の広さの違いではなく、その区間に何が言えるかという解釈の違いが理由。広さだけでは言い切り方は決まらない。", "計算方法も解釈もどちらも異なる。信頼区間は頻度主義、信用区間はベイズ主義というそれぞれ別の立場から作られている。"]}'),

  ('stats14-q06', 'ベイズ統計の応用',
   '新しい薬の効果を調べる実験をした。得られた結果は、『薬に効果がある』という仮説のもとでは起こる確率(尤度)が0.4、『薬に効果がない』という仮説のもとでは起こる確率(尤度)が0.1だった。この2つの尤度の比0.4÷0.1を計算して、どちらの仮説を証拠がどれだけ支持しているかを比べる指標を何と呼ぶ？',
   NULL::text,
   '["ベイズファクター。2つの仮説それぞれの尤度の比をとり、証拠の支持の強さを比べる指標。", "事後確率。証拠を見たあとに計算し直された、それぞれの仮説がそれらしいと言える確率のこと。", "有意水準。仮説検定であらかじめ決めておく、帰無仮説を棄却するかどうかの基準の値。", "信用区間。事後分布の中で、真の値がある可能性が高い範囲を幅で示した値のこと。"]',
   0, '[0]', 'single',
   '{"asked": "2つの仮説のどちらを証拠がどれくらい支持しているかを、尤度の比で比べる指標。", "point": "ベイズファクター＝仮説1の尤度÷仮説2の尤度。数字が大きいほど、仮説1を強く支持する証拠だと分かる。", "kid": "『効果がある』と『効果がない』、2つの仮説のうちどちらが正しそうかを、今回の実験結果がそれぞれの仮説のもとでどれくらい起こりやすかったか(尤度)を比べることで判断する数。比が大きいほど、片方の仮説がより支持されている。", "eg": "2人の目撃者の証言のうち、犯人がAさんだと考えるとつじつまが合う確率と、犯人がBさんだと考えるとつじつまが合う確率を比べて、どちらの説がより証言と合っているかを判断するようなもの。比べる対象は『それぞれの仮説のもとでの、証拠の出やすさ』。", "viz": "<svg viewBox=\"0 0 340 132\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">2つの仮説それぞれの尤度を比べる</text>\n<text x=\"80\" y=\"36\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">効果がある</text>\n<rect x=\"30\" y=\"46\" width=\"100\" height=\"18\" fill=\"#2a2f3f\"/><rect x=\"30\" y=\"46\" width=\"40\" height=\"18\" fill=\"#3b82f6\"/>\n<text x=\"80\" y=\"78\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">尤度 0.4</text>\n<text x=\"260\" y=\"36\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">効果がない</text>\n<rect x=\"210\" y=\"46\" width=\"100\" height=\"18\" fill=\"#2a2f3f\"/><rect x=\"210\" y=\"46\" width=\"10\" height=\"18\" fill=\"#3b82f6\"/>\n<text x=\"260\" y=\"78\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">尤度 0.1</text>\n<text x=\"170\" y=\"100\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">0.4 ÷ 0.1 = 4</text>\n<text x=\"170\" y=\"118\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">証拠は「効果がある」を4倍支持</text>\n</svg>", "terms": [["ベイズファクター", "2つの仮説それぞれのもとでの尤度の比。証拠がどちらの仮説をどれくらい支持しているかを表す"], ["尤度", "ある仮説(原因)を仮定したときに、その結果がどれくらい出やすいかを表す確率(既存セットで既出)"]], "think": "なぜ引き算ではなく比(割り算)で比べるのかがカギ。尤度そのものは『その仮説のもとで、今回の結果がどれくらい出やすかったか』という単独の数字で、片方の仮説だけを見ても『他の仮説と比べて強いのか弱いのか』は分からない。2つの尤度を割り算にして比にすることで、『効果があるという仮説は、効果がないという仮説の何倍、今回の結果を説明しやすいか』という、比較のものさしになる。だから比で表す。", "vs": "p値(仮説検定セットで既出)は『帰無仮説が正しいと仮定したときに、今回以上に極端な結果が出る確率』という1つの仮説だけを見る指標。ベイズファクターは2つの仮説を直接比べる点で、そもそも見ているものが違う。", "why_asked": "仮説検定(既存セット)では『帰無仮説を棄却するかどうか』の一方通行の判断しかできなかった。ベイズファクターを使うと『どちらの仮説をどれだけ支持するか』を、2つの仮説を対等に並べて比べられる。", "usecase": "新薬の効果の有無を比べる臨床試験、2つの仮説(このメールは迷惑メールか、そうでないか)のどちらが証拠に合うかを判断する場面など。", "calc": "薬に効果がある場合の尤度   0.4\n薬に効果がない場合の尤度   0.1\nベイズファクター          0.4 ÷ 0.1 = 4\n読み方                   証拠は「効果がある」を「効果がない」の4倍支持", "opt": ["正解。0.4÷0.1=4。2つの仮説それぞれのもとでの尤度の比をとり、証拠がどちらをどれだけ支持するかを表すのがベイズファクター。", "事後確率は証拠を見たあとの、それぞれの仮説そのものの確率。今回の0.4÷0.1という比の計算は、事後確率を直接求める式ではない。", "有意水準は仮説検定で先に決めておく基準の値で、実験結果から計算する指標ではない。今回のような尤度の比とは別物。", "信用区間は事後分布の中の範囲を示す幅であって、2つの仮説を比べる比の値ではない。"]}'),

  ('stats14-q07', 'ベイズ統計の応用',
   '同じチェーンの5店舗のカフェで、1日の来客数の『その店らしい多さ』を推定したい。各店舗を完全に別々に(他の店のデータは一切使わず)推定する方法と、『同じチェーンなので、店舗ごとに多少違うが、まったくバラバラでもないはず』と仮定して、店舗間で情報を少しずつ融通し合いながら推定する方法がある。後者の考え方を何と呼ぶ？',
   NULL::text,
   '["階層ベイズモデル。グループごとに違うが、まったくバラバラでもないと仮定し、情報を融通し合う考え方。", "共役事前分布。事前分布と事後分布が同じ種類の分布のままになる、計算上都合の良い組み合わせ。", "逐次ベイズ更新。証拠が増えるたびに、前回の事後分布を次の事前分布として使い、更新を繰り返す考え方。", "MAP推定。事後分布の中で確率が一番高い1点を、代表の答えとして選ぶ考え方。"]',
   0, '[0]', 'single',
   '{"asked": "似ているが少しずつ違うグループどうしで、情報を融通し合いながら推定する考え方の名前。", "point": "階層ベイズモデルは『グループごとに違うが、まったくバラバラでもない』と仮定し、データが少ないグループを他のグループの情報で補う。", "kid": "5店舗を完全に別々に見ると、来客数が少ない店舗はデータ不足で推定がブレやすい。でも『同じチェーンだから、多少似ているはず』という前提を置くと、他の店舗のデータも参考にしながら、それぞれの店舗の推定を安定させられる。この『少し似ている』という前提を使うのが階層ベイズモデル。", "eg": "兄弟姉妹の身長を予想するとき、1人だけの情報で予想するより、『同じ親から生まれた兄弟は身長の傾向が似る』という前提を使い、他の兄弟の身長も参考にしたほうが、データが少ない子でもそれらしい予想ができる。店舗どうしも『同じチェーン』という共通の親のようなもの。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">5店舗、少しずつ違うが情報を融通し合う</text>\n<ellipse cx=\"170\" cy=\"52\" rx=\"60\" ry=\"20\" fill=\"#3b82f6\" opacity=\"0.35\"/>\n<text x=\"170\" y=\"56\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">チェーン全体の傾向</text>\n<circle cx=\"45\" cy=\"105\" r=\"15\" fill=\"#2a2f3f\" stroke=\"#60a5fa\"/><text x=\"45\" y=\"109\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">店A</text>\n<circle cx=\"110\" cy=\"112\" r=\"15\" fill=\"#2a2f3f\" stroke=\"#60a5fa\"/><text x=\"110\" y=\"116\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">店B</text>\n<circle cx=\"170\" cy=\"115\" r=\"15\" fill=\"#2a2f3f\" stroke=\"#60a5fa\"/><text x=\"170\" y=\"119\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">店C</text>\n<circle cx=\"230\" cy=\"112\" r=\"15\" fill=\"#2a2f3f\" stroke=\"#60a5fa\"/><text x=\"230\" y=\"116\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">店D</text>\n<circle cx=\"295\" cy=\"105\" r=\"15\" fill=\"#2a2f3f\" stroke=\"#60a5fa\"/><text x=\"295\" y=\"109\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">店E</text>\n<line x1=\"55\" y1=\"93\" x2=\"145\" y2=\"65\" stroke=\"#60a5fa\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n<line x1=\"295\" y1=\"93\" x2=\"200\" y2=\"65\" stroke=\"#60a5fa\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n<line x1=\"170\" y1=\"100\" x2=\"170\" y2=\"72\" stroke=\"#60a5fa\" stroke-width=\"1\" stroke-dasharray=\"2 2\"/>\n</svg>", "terms": [["階層ベイズモデル", "グループ(店舗・学校など)ごとに違うが、まったくバラバラでもないと仮定し、グループ間で情報を融通し合って推定するベイズ統計の考え方"], ["情報の融通", "データが少ないグループの推定を、他のグループのデータも参考にして安定させること"]], "think": "なぜ完全に別々に推定するより安定するのかがカギ。データが少ない店舗を単独で見ると、たまたま少ない日数のデータに引っぱられて、実際より極端な推定(異様に多い・少ない)になりやすい。階層ベイズモデルは『チェーン全体としての、来客数のだいたいの傾向』も同時に推定し、各店舗の推定をその全体の傾向のほうへ少し引き寄せる。データが少ない店舗ほど、この引き寄せの効果が強くはたらき、極端な推定を防いでくれる。データが多い店舗は自分自身のデータで十分推定できるので、引き寄せの効果は弱くなる。", "vs": "『全店舗まとめて1つの平均だけを出す』のとも違う。階層ベイズモデルは各店舗ごとの個性(その店らしい多さ)は残したまま、極端になりすぎないよう全体の傾向で軽く支えるという、両方のいいとこ取りをする考え方。", "why_asked": "現実のデータは、学校ごと・店舗ごと・患者ごとのように、いくつかのグループに自然に分かれていることが多い。グループごとに完全に別々に見るか、全部まとめて1つに見るかの二択ではなく、その中間を扱えるのが階層ベイズモデルの強み。", "usecase": "チェーン店ごとの売上予測、学校ごとのテスト平均の比較、病院ごとの治療成績の比較など、グループ間でデータの量に差がある場面で特に効果を発揮する。", "opt": ["正解。店舗(グループ)ごとに違うが、まったくバラバラでもないと仮定し、情報を融通し合いながら推定するのが階層ベイズモデル。", "共役事前分布は、事前分布と事後分布の『分布の種類』が保たれるかという計算上の話で、店舗どうしの情報の融通とは別の話。", "逐次ベイズ更新は、証拠が届くたびに1つの対象について更新を繰り返す話。複数のグループ間で情報を融通する話とは別。", "MAP推定は、できあがった事後分布から代表の1点を選ぶ方法。複数のグループの情報をどう組み合わせるかという今回の話とは別。"]}'),

  ('stats14-q08', 'ベイズ統計の応用',
   '複雑な事後分布は、数式できれいに解けないことが多い。そこで、事後分布の形になるべく従うように、たくさんの『試しの値』をコンピュータに次々と生成させ、その値の集まりから分布の形を浮かび上がらせるやり方がある。この考え方を何と呼ぶ？',
   NULL::text,
   '["MCMC（マルコフ連鎖モンテカルロ法）。たくさんの試行を生成し、その集まりから事後分布の形を近似するやり方。", "共役事前分布。事前分布と事後分布が同じ種類の分布のままになる、数式だけで正確に解ける、都合の良い組み合わせ。", "MAP推定。すでに求まった事後分布の中で確率が一番高い1点を、代表の答えとして選ぶやり方。", "ベイズファクター。2つの仮説それぞれの尤度の比をとり、証拠の支持の強さがどちらにあるかを比べる指標。"]',
   0, '[0]', 'single',
   '{"asked": "数式で解けない複雑な事後分布を、たくさんの試行から近似するやり方の名前。", "point": "MCMCは、事後分布の形に従うようたくさんのサンプルを生成し、そのサンプルの集まりの形で事後分布そのものを近似する。", "kid": "事後分布の式が複雑すぎて、数式を解いて『山の形はこうです』ときれいに求められないことがある。そこで、事後分布に従うような『試しの値』をコンピュータにたくさん(何千・何万と)作らせ、その値がどのあたりに集まったかを見ることで、山の形を浮かび上がらせるのがMCMC。", "eg": "山の形をした土地の等高線図を、正確な測量図が無い状態で知りたいとき、目隠しをした人にその土地をたくさん歩き回らせ、『どのあたりに長く立ち止まったか』を記録すれば、立ち止まった回数が多い場所ほど土地が高い(頂上に近い)とおおよそ分かる。数式で測量する代わりに、たくさんの試行の記録から形を浮かび上がらせる発想がMCMCと同じ。", "viz": "<svg viewBox=\"0 0 340 132\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">たくさんの試行(サンプル)の集まりが山を描く</text>\n<circle cx=\"80\" cy=\"98\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"95\" cy=\"102\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"110\" cy=\"88\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"120\" cy=\"94\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"135\" cy=\"70\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"145\" cy=\"60\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"150\" cy=\"80\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"160\" cy=\"50\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"168\" cy=\"55\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"175\" cy=\"45\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"180\" cy=\"62\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"190\" cy=\"52\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"198\" cy=\"68\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"210\" cy=\"58\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"220\" cy=\"78\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"228\" cy=\"90\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"238\" cy=\"85\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"248\" cy=\"96\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"258\" cy=\"100\" r=\"2.3\" fill=\"#60a5fa\"/><circle cx=\"270\" cy=\"104\" r=\"2.3\" fill=\"#60a5fa\"/>\n<line x1=\"30\" y1=\"112\" x2=\"310\" y2=\"112\" stroke=\"#2a2f3f\"/>\n<text x=\"170\" y=\"128\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">点が多く集まった場所ほど、事後分布が高い</text>\n</svg>", "terms": [["MCMC(マルコフ連鎖モンテカルロ法)", "事後分布に従うようなサンプルをたくさん生成し、その集まりから分布の形を近似する計算手法"], ["サンプリング", "分布に従うような値を、コンピュータにひとつずつ生成させること"]], "think": "なぜ数式を解く代わりに試行を繰り返すのかがカギ。事後分布は、扱う仮説や証拠の種類が増えるほど、数式で正確に解くのがどんどん難しくなる(共役事前分布のような都合の良い組み合わせが使えない場合はなおさら)。MCMCは『正確な式を解く』のをあきらめる代わりに、『事後分布が高いところほど、試しの値がたくさん生成されるような、うまい生成のルール』を使う。生成された試しの値をたくさん集めて集計すれば、値が多く集まった場所ほど事後分布が高い場所だと分かり、複雑な式を一切解かずに、事後分布の形をおおよそ再現できる。", "vs": "共役事前分布は『数式で正確に解ける』組み合わせを選ぶ工夫。MCMCは『数式で解けない場合に、試行で近似する』別の解決策。目的は同じ(事後分布を知りたい)でも、アプローチが違う。", "why_asked": "実務で使われるベイズ統計の多くは、共役事前分布のような都合の良い組み合わせが使えない複雑なモデルを扱う。そこでMCMCのような、試行を繰り返して近似する計算手法が欠かせない道具になる。", "usecase": "複雑な階層ベイズモデルの計算、機械学習の一部のモデルの学習、天気予報の複雑なシミュレーションなど、数式で正確に解けない問題を扱う統計ソフトの内部で広く使われている。", "opt": ["正解。事後分布に従うようたくさんの試しの値(サンプル)を生成し、その集まりから分布の形を近似するのがMCMC。", "共役事前分布は数式で正確に解ける都合の良い組み合わせを選ぶ工夫。今回の『試行を繰り返して近似する』話とは逆のアプローチ。", "MAP推定は、すでに求まった事後分布から代表の1点を選ぶ方法。今回問われているのは、事後分布そのものをどう求めるかという話。", "ベイズファクターは2つの仮説の尤度の比を比べる指標であって、事後分布の形をどう求めるかという今回の話とは別物。"]}'),

  ('stats14-q09', 'ベイズ統計の応用',
   '迷惑メール判定システムは、メールの中に『無料』『今すぐ』『当選』のような単語がそれぞれ含まれているかどうかを手がかりに、ベイズの定理を使って『このメールが迷惑メールである確率』を計算し、しきい値を超えたら迷惑メールと判定する。この、ベイズの定理を機械学習の分類に応用した手法を何と呼ぶ？',
   NULL::text,
   '["ナイーブベイズ分類器。ベイズの定理を使い、いくつかの手がかりからどちらのグループに属するかを判定する手法。", "階層ベイズモデル。グループごとに違うが、まったくバラバラでもないと仮定して、情報を融通し合っていく考え方。", "MCMC。複雑な事後分布を、たくさんの試行を生成することで近似する計算手法のこと。", "信用区間。事後分布の中で、真の値がある可能性が高い範囲を、幅で示す考え方のこと。"]',
   0, '[0]', 'single',
   '{"asked": "ベイズの定理を、機械学習の『分類』というタスクに応用した具体的な手法の名前。", "point": "ナイーブベイズ分類器は、いくつかの手がかり(単語の有無など)から、ベイズの定理を使って『迷惑メールらしさ』のような確率を計算し、グループ分けする手法。", "kid": "『無料』という単語が入っている、『今すぐ』という単語も入っている、といった手がかりを1つずつ集め、ベイズの定理を使って『この手がかりが揃うなら、迷惑メールである確率はこれくらい』と計算し、確率が高ければ迷惑メールに分類する仕組み。", "eg": "お医者さんが、熱がある・咳が出る・味がしない、といった症状(手がかり)を1つずつ聞き取り、それぞれの症状があるときの病気の起こりやすさ(尤度)を踏まえて『この病気である確率はこれくらい』と診断するのと同じ発想。ナイーブベイズ分類器は、これを単語の手がかりでメールに対して行っている。", "viz": "<svg viewBox=\"0 0 340 136\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">単語の手がかりから迷惑メールらしさを計算</text>\n<rect x=\"20\" y=\"32\" width=\"56\" height=\"20\" fill=\"#2a2f3f\" stroke=\"#60a5fa\"/><text x=\"48\" y=\"46\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">「無料」</text>\n<rect x=\"20\" y=\"58\" width=\"56\" height=\"20\" fill=\"#2a2f3f\" stroke=\"#60a5fa\"/><text x=\"48\" y=\"72\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">「今すぐ」</text>\n<rect x=\"20\" y=\"84\" width=\"56\" height=\"20\" fill=\"#2a2f3f\" stroke=\"#60a5fa\"/><text x=\"48\" y=\"98\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\">「当選」</text>\n<line x1=\"76\" y1=\"42\" x2=\"140\" y2=\"66\" stroke=\"#8892a4\"/><line x1=\"76\" y1=\"68\" x2=\"140\" y2=\"68\" stroke=\"#8892a4\"/><line x1=\"76\" y1=\"94\" x2=\"140\" y2=\"70\" stroke=\"#8892a4\"/>\n<rect x=\"140\" y=\"52\" width=\"72\" height=\"34\" fill=\"#3b82f6\"/><text x=\"176\" y=\"73\" fill=\"#141720\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"700\">ベイズの定理</text>\n<line x1=\"212\" y1=\"68\" x2=\"250\" y2=\"68\" stroke=\"#8892a4\"/>\n<rect x=\"250\" y=\"52\" width=\"70\" height=\"34\" fill=\"#60a5fa\"/><text x=\"285\" y=\"66\" fill=\"#141720\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"700\">迷惑メール</text><text x=\"285\" y=\"78\" fill=\"#141720\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"700\">である確率</text>\n<text x=\"170\" y=\"120\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">手がかりが揃うほど確率は変わる</text>\n</svg>", "terms": [["ナイーブベイズ分類器", "ベイズの定理を使い、いくつかの手がかりから、どちらのグループに属するかを確率で判定する機械学習の分類手法"], ["特徴量", "判定の手がかりとして使う情報。メール分類なら『無料という単語が入っているか』のような1つ1つの手がかり"]], "think": "なぜ『ナイーブ(単純)』という名前が付いているのかがカギ。『無料』という単語と『今すぐ』という単語は、実際のメールでは一緒に出てきやすいなど、手がかりどうしが互いに関係し合っていることが多い。ナイーブベイズ分類器は計算を単純にするため、こうした手がかりどうしの関係をいったん無視して、『それぞれの手がかりは独立に迷惑メールらしさに効いている』とみなして計算する。この単純化(ナイーブ)のおかげで計算がとても軽くなり、多少大ざっぱでも実用上は十分な精度で分類できることが多い。", "vs": "階層ベイズモデルは複数のグループ間で情報を融通し合う話で、目的は『グループごとの推定を安定させる』こと。ナイーブベイズ分類器は複数の手がかりから1つの対象(メール)を分類する話で、目的が違う。", "why_asked": "ここまで学んだ事前確率・尤度・事後確率・条件付き確率(既存セット)といった部品が、実際の機械学習の道具としてどう組み立てられているかを知る、ベイズ統計の応用の入り口。", "usecase": "迷惑メール判定のほか、文章のジャンル分類、簡易な医療診断支援、レビューの好意的/否定的判定など、いくつかの手がかりから素早く分類したい場面で広く使われる、実装が軽く扱いやすい手法。", "opt": ["正解。単語などの手がかりから、ベイズの定理を使って『迷惑メールらしさ』を計算し分類するのがナイーブベイズ分類器。", "階層ベイズモデルは複数のグループ間で情報を融通し合う話。今回のような、1通のメールを手がかりから分類する話とは目的が異なる。", "MCMCは複雑な事後分布を試行で近似する計算手法。今回のような分類の手法そのものの名前ではない。", "信用区間は事後分布の中の範囲を示す幅の値であって、メールを迷惑メールかどうかに分類する手法ではない。"]}'),

  ('stats14-q10', 'ベイズ統計の応用',
   'ここまでベイズ主義(確信の度合いとして確率を扱う立場)と頻度主義(繰り返しの割合として確率を扱う立場)を見てきた。実際の統計や機械学習の現場では、この2つの立場はどう扱われていることが多い？',
   NULL::text,
   '["対立して片方だけが正しいというより、目的やデータの性質に応じて、場面ごとに使い分けられている。", "ベイズ主義が頻度主義を完全に置き換えており、実務では頻度主義の手法はほとんど使われなくなっている。", "頻度主義がベイズ主義を完全に置き換えており、実務ではベイズ主義の手法はほとんど使われなくなっている。", "2つの立場は計算結果が常に一致するため、実務ではどちらを選んでも違いが出ることはない。"]',
   0, '[0]', 'single',
   '{"asked": "ベイズ主義と頻度主義、実務ではどちらの立場が使われているのかという、まとめの問い。", "point": "対立ではなく使い分け。事前の知識を活かしたい・少ないデータで判断したいならベイズ、大量データで手順の保証を重視するなら頻度主義、というように場面で選ぶ。", "kid": "ベイズ主義と頻度主義は、どちらかが完全に正しくてもう片方が間違っている、という関係ではない。過去の知識をうまく使いたい場面ではベイズ主義が向いていて、大量のデータをもとに手堅く判断したい場面では頻度主義が向いている、というように、実務では場面ごとに選ばれている。", "eg": "料理でいうと、和包丁と洋包丁のどちらが『正しい包丁』かを競うようなものではなく、刺身を引くなら和包丁、肉を切り分けるなら洋包丁というように、用途で使い分けるのに近い。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\">\n<text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">対立ではなく、場面ごとの使い分け</text>\n<rect x=\"24\" y=\"28\" width=\"130\" height=\"94\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<text x=\"89\" y=\"44\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">ベイズ主義</text>\n<text x=\"89\" y=\"62\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">少ないデータ</text>\n<text x=\"89\" y=\"78\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">過去の知識を活かす</text>\n<text x=\"89\" y=\"94\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">1回きりの予測</text>\n<rect x=\"186\" y=\"28\" width=\"130\" height=\"94\" fill=\"none\" stroke=\"#2a2f3f\"/>\n<text x=\"251\" y=\"44\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">頻度主義</text>\n<text x=\"251\" y=\"62\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">大量データ</text>\n<text x=\"251\" y=\"78\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">手順の保証を重視</text>\n<text x=\"251\" y=\"94\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">繰り返し可能な実験</text>\n<text x=\"170\" y=\"136\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">目的に合わせて選ぶ道具</text>\n</svg>", "terms": [["ベイズ主義", "確率を、今ある証拠からの確信の度合いとして捉える立場(既存セットで既出)"], ["頻度主義", "確率を、同じ状況を繰り返したときの長期的な割合として捉える立場(既存セットで既出)"]], "think": "なぜ『対立』ではなく『使い分け』なのかがカギ。ベイズ主義は事前分布という形で過去の知識やデータの少なさを補えるので、データが少ない場面や、新薬の効果のように1回きりの意思決定が必要な場面に強い。頻度主義は『同じ手順を繰り返したときにどれくらい信頼できるか』を保証する考え方なので、大量のデータがあり、手順そのものの正しさを厳密に示したい場面(工場の品質基準など)に強い。どちらも一長一短があり、目的が違えば向き不向きも変わるので、実務ではその都度どちらの道具を使うかを選んでいる。", "vs": "『新しいベイズ統計のほうが古い頻度主義より優れている』という理解は誤り。歴史的には頻度主義の手法(このドリルの推測統計・仮説検定セット)が先に整備され、今も広く使われている。ベイズ統計はそれとは別の強みを持つ、もう1つの道具として併存している。", "why_asked": "このドリルでは推測統計・仮説検定(頻度主義寄り)とベイズ統計(ベイズ主義寄り)を別々のセットとして学んできた。両方を『対立する2つの正解のうちどちらかを選ぶもの』と誤解しないよう、実務での関係を最後に整理しておく。", "usecase": "新薬の初期の少人数試験ではベイズ統計で見込みを更新しながら判断し、大規模な最終試験では頻度主義の仮説検定で厳密に判定する、というように、同じプロジェクトの中でも段階に応じて両方が使われることがある。", "opt": ["正解。データの性質や目的に応じて、ベイズ主義と頻度主義はそれぞれ得意な場面で使い分けられている。", "頻度主義の手法(仮説検定、信頼区間など)は現在も品質管理や大規模な実験で広く使われており、置き換えられてはいない。", "ベイズ主義の手法(階層ベイズモデル、MCMCなど)も現在の機械学習や少数データの分析で広く使われており、置き換えられてはいない。", "同じデータでも、事前分布の置き方や解釈の違いにより、2つの立場は異なる結果や異なる言い切り方になることがある。"]}')


) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
